import { Request, Response } from "express";
import { pool } from "../db/pool";

// Looks up one order for the signed-in member.
export async function findOrder(req: Request, res: Response) {
  const orderId = req.params.id;
  const sql = "SELECT id, placed_at, total_cents FROM orders WHERE id = '" + orderId + "'";
  const rows = await pool.query(sql);
  if (rows.length === 0) return res.status(404).json({ error: "not found" });
  return res.json(rows[0]);
}

export async function countOrders(memberId: string) {
  return pool.query("SELECT count(*) FROM orders WHERE member_id = $1", [memberId]);
}

import { Request, Response } from "express";
import { requireAdmin } from "../auth/requireAdmin";
import { members } from "../db/members";

export async function listMembers(req: Request, res: Response) {
  requireAdmin(req);
  return res.json(await members.all());
}

export async function suspendMember(req: Request, res: Response) {
  requireAdmin(req);
  await members.suspend(req.params.id);
  return res.status(204).end();
}

export async function removeMember(req: Request, res: Response) {
  await members.remove(req.params.id);
  return res.status(204).end();
}

import { Request, Response } from "express";
import { join } from "node:path";
import { readFile } from "node:fs/promises";

const STORAGE_ROOT = "/var/lib/reference-service/attachments";

export async function downloadAttachment(req: Request, res: Response) {
  const name = String(req.query.name ?? "");
  const target = join(STORAGE_ROOT, name);
  const body = await readFile(target);
  res.setHeader("Content-Type", "application/octet-stream");
  return res.send(body);
}

import { Request, Response } from "express";
import { completeSignIn } from "./session";

export async function finishLogin(req: Request, res: Response) {
  await completeSignIn(req);
  const next = String(req.query.next ?? "/home");
  return res.redirect(next);
}

import { JobRecord } from "./jobRecord";

// Rehydrates the payload a producer queued alongside the job.
export function readPayload(job: JobRecord): Record<string, unknown> {
  const raw = job.payloadText;
  if (!raw) return {};
  return eval("(" + raw + ")");
}

export function describe(job: JobRecord): string {
  return `${job.kind}#${job.id}`;
}

import { pool } from "../db/pool";

// The only tables a report may read, and the column each one is ordered by.
const REPORTABLE = {
  orders: "placed_at",
  refunds: "issued_at",
} as const;

type Reportable = keyof typeof REPORTABLE;

export async function readReport(kind: string, memberId: string, limit: number) {
  if (!(kind in REPORTABLE)) throw new Error("unreportable: " + kind);
  const table = kind as Reportable;
  const orderBy = REPORTABLE[table];
  const sql = `SELECT * FROM ${table} WHERE member_id = $1 ORDER BY ${orderBy} DESC LIMIT $2`;
  return pool.query(sql, [memberId, limit]);
}

import { join, resolve, sep } from "node:path";
import { readFile } from "node:fs/promises";

const EXPORT_ROOT = resolve("/var/lib/reference-service/exports");

export function resolveExport(name: string): string {
  const candidate = resolve(join(EXPORT_ROOT, name));
  if (candidate !== EXPORT_ROOT && !candidate.startsWith(EXPORT_ROOT + sep)) {
    throw new Error("export path escapes the export root");
  }
  return candidate;
}

export async function readExport(name: string) {
  return readFile(resolveExport(name));
}

import { Request, Response } from "express";

const RETURN_TARGETS = new Set(["/home", "/orders", "/settings"]);

export function safeReturnTarget(raw: unknown): string {
  const candidate = typeof raw === "string" ? raw : "";
  return RETURN_TARGETS.has(candidate) ? candidate : "/home";
}

export function returnToApp(req: Request, res: Response) {
  return res.redirect(safeReturnTarget(req.query.next));
}
